def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    for _, opp in history:
        if opp == 'C':
            opp_c += 1
    rate = opp_c / n

    w = min(16, n)
    rc = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            rc += 1
    rrate = rc / w

    tailD = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            tailD += 1
        else:
            break

    tailC = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            tailC += 1
        else:
            break

    last_conf = -1
    last_pun = -1
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'C':
                last_conf = i
            else:
                last_pun = i

    exploit = (
        rate > 0.55 and
        rrate > 0.45 and
        last_conf >= 0 and
        last_conf > last_pun and
        n - last_conf <= 40
    )

    if exploit and tailD == 0 and tailC >= 2 and rrate >= 0.5:
        return 'D'

    can_probe = last_pun < 0 or (n - last_pun > 70)

    if (
        last_opp == 'C' and
        last_me == 'C' and
        can_probe and
        tailC >= 5 and
        rate > 0.68 and
        rrate > 0.5 and
        n < 95
    ):
        return 'D'

    if last_opp == 'D':
        if n >= 2:
            pm, po = history[-2]

            if pm == 'D' and po == 'C' and last_me == 'C':
                if rate > 0.35 and rc > 2:
                    return 'C'

            if pm == 'D' and po == 'C' and last_me == 'D':
                if rate > 0.55 and rc > 2 and tailD <= 2:
                    return 'C'

            if pm == 'D' and po == 'D' and last_me == 'C':
                if rate > 0.25 and tailD <= 6:
                    return 'C'

        if tailD == 1 and last_me == 'C' and rate > 0.80 and rrate >= 0.6:
            return 'C'

        if rate > 0.75:
            limit = 2
        elif rate > 0.50:
            limit = 3
        elif rate > 0.25:
            limit = 5
        else:
            limit = 1000

        if last_me == 'D':
            if tailD >= limit:
                return 'C'
            return 'D'

        return 'D'

    if last_me == 'D':
        return 'C'

    return 'C'
